import{_ as i,a8 as s,o as v,c as h,ah as p,a as t,K as a,L as l,a3 as o}from"./chunks/framework.BNwxUeRp.js";import"./chunks/theme.BC7t94LL.js";const A=JSON.parse('{"title":"Jev 概述","description":"","frontmatter":{"title":"Jev 概述","abstract":"Jev 概述，介绍 TypeSafe AI 推出的面向决策的 AI 模型，讲解其 Decisions not strings 核心理念及与传统 LLM 的本质差异。","created":"2026-09-23T00:00:00.000Z","tags":["AI","Jev","决策模型"],"type":"概念解释","related":["[[Jev-MOC]]","[[Jev-决策调用模型]]","[[Jev-三大决策原语]]","[[Jev-与传统LLM的区别]]"],"reference":"","category":["🧩 AI框架与Agent","Jev"]},"headers":[],"relativePath":"vault/Knowledge/AI/Jev-概述.md","filePath":"vault/Knowledge/AI/Jev-概述.md","lastUpdated":1790655645000}'),b={name:"vault/Knowledge/AI/Jev-概述.md"};function g(u,e,c,J,f,m){const n=s("VPNolebaseInlineLinkPreview"),r=s("NolebaseGitContributors"),d=s("NolebaseGitChangelog");return v(),h("div",null,[e[6]||(e[6]=p(`<h1 id="jev-概述" tabindex="-1">Jev 概述 <a class="header-anchor" href="#jev-概述" aria-label="Permalink to “Jev 概述”">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to “定义”">​</a></h2><p><strong>Jev</strong> 是 TypeSafe AI 推出的、面向「决策」的 AI 模型。它与 GPT / Claude 这类传统大语言模型（LLM）的差别不在于「谁更聪明」，而在于<strong>两者从一开始就在解决不同的问题</strong>：</p><blockquote><p><strong>传统 LLM 主要负责生成内容，而 Jev 主要负责做判断。</strong></p></blockquote><p>所以 Jev 的定位不是面向用户聊天的 AI 助手，而是<strong>供软件调用的「智能判断器」</strong>——可以理解为隐藏在系统内部的一个<strong>「智能 if 语句」</strong>。</p><table tabindex="0"><thead><tr><th></th><th>传统 LLM 的典型任务</th><th>Jev 关注的判断</th></tr></thead><tbody><tr><td>任务</td><td>写文章、写代码、回答问题、总结内容、生成方案</td><td>这是什么？选哪个？要不要？风险多高？是否需要人工？下一步走哪个流程？</td></tr><tr><td>输出形态</td><td>自然语言 / JSON 文本</td><td>结构化决策（附带置信度）</td></tr><tr><td>主要消费方</td><td>人</td><td>程序</td></tr></tbody></table><h2 id="核心理念-decisions-not-strings" tabindex="-1">核心理念：Decisions, not strings <a class="header-anchor" href="#核心理念-decisions-not-strings" aria-label="Permalink to “核心理念：Decisions, not strings”">​</a></h2><p>传统做法是「让模型生成一段文字，再由程序解析」；Jev 主张<strong>不要让 AI 生成字符串，而是直接让 AI 给出决策</strong>。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>传统 LLM：输入 → 模型生成自然语言 → 程序解析文本 → 得到业务结果</span></span>
<span class="line"><span>Jev：    输入状态 → Jev → 直接得到结构化决策 → 程序执行</span></span></code></pre></div><p>以「客户要求退款」为例：</p><ul><li>传统 LLM 可能输出「从客户的描述来看，其核心诉求是退款，同时存在物流问题……因此建议将该工单分配给退款部门」，程序仍需从中解析出 <code>category = refund</code>；</li><li>Jev 直接返回 <code>{&quot;category&quot;: &quot;refund&quot;, &quot;confidence&quot;: 0.94}</code>，程序可以立即使用。</li></ul><h2 id="为什么需要-jev" tabindex="-1">为什么需要 Jev <a class="header-anchor" href="#为什么需要-jev" aria-label="Permalink to “为什么需要 Jev”">​</a></h2><p>很多软件内部其实既不需要一篇文章，也不需要几十行推理，只需要一个「是/否」或一个类别：</p><table tabindex="0"><thead><tr><th>实际需求</th><th>真正需要的结果</th></tr></thead><tbody><tr><td>这封邮件是不是退款申请？</td><td><code>Yes</code></td></tr><tr><td>应该调用搜索工具还是数据库工具？</td><td><code>database</code></td></tr><tr><td>客户紧急程度是多少？</td><td><code>4 / 5</code></td></tr></tbody></table><p>如果这些高频、边界明确的判断全部交给大型生成式模型，就会额外付出：<strong>延迟、Token 消耗、推理成本、输出解析工作、格式错误风险</strong>。Jev 的思路是把这类「智能判断」从通用 LLM 中拆出来，交给专门的决策模型。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2>`,16)),t("ul",null,[t("li",null,[a(n,{href:"/nebula-blog/vault/Knowledge/AI/Jev-决策调用模型.html"},{default:l(()=>[...e[0]||(e[0]=[o("Jev-决策调用模型",-1)])]),_:1}),e[1]||(e[1]=o("：State + Question → 结构化决策",-1))]),t("li",null,[a(n,{href:"/nebula-blog/vault/Knowledge/AI/Jev-三大决策原语.html"},{default:l(()=>[...e[2]||(e[2]=[o("Jev-三大决策原语",-1)])]),_:1}),e[3]||(e[3]=o("：Noul / Choice / Score",-1))]),t("li",null,[a(n,{href:"/nebula-blog/vault/Knowledge/AI/Jev-与传统LLM的区别.html"},{default:l(()=>[...e[4]||(e[4]=[o("Jev-与传统LLM的区别",-1)])]),_:1})]),t("li",null,[a(n,{href:"/nebula-blog/vault/Knowledge/AI/Jev-适用场景与局限.html"},{default:l(()=>[...e[5]||(e[5]=[o("Jev-适用场景与局限",-1)])]),_:1})])]),e[7]||(e[7]=t("p",null,[t("em",null,"（内容由AI生成，仅供参考）")],-1)),a(r),a(d)])}const I=i(b,[["render",g]]);export{A as __pageData,I as default};
